select '3d7f2e44-0e2d-4b66-9f7a-0c4d1c5b8a11',key,parent,topic,title,description,level,null,'verified','{"authority":"Cambridge International","sourceDocument":"https://www.cambridgeinternational.org/Images/664563-2025-2027-syllabus.pdf","retrievedAt":"2026-09-29","mappingStatus":"verified","representation":"normalized_official_outcomes"}'::jsonb from jsonb_to_recordset('[{"key":"1","parent":null,"topic":null,"title":"Atomic structure","description":"Chemistry 9701 Topic 1: Atomic structure","level":"as_level"},{"key":"1.1.1","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Understand that atoms are mostly empty space surrounding a very small, dense nucleus containing protons and neutrons, with electrons in shells around the nucleus.","level":"as_level"},{"key":"1.1.2","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Identify and describe protons, neutrons and electrons by their relative charges and masses.","level":"as_level"},{"key":"1.1.3","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Understand atomic number, proton number, mass number and nucleon number.","level":"as_level"},{"key":"1.1.4","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Describe the distribution of mass and charge within an atom.","level":"as_level"},{"key":"1.1.5","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Describe the behaviour of proton, neutron and electron beams moving at the same velocity in an electric field.","level":"as_level"},{"key":"1.1.6","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"Determine the numbers of protons, neutrons and electrons in atoms and ions from atomic/proton number, mass/nucleon number and charge.","level":"as_level"},{"key":"1.1.7","parent":"1.1","topic":"1.1","title":"Particles in the atom and atomic radius","description":"State and explain qualitatively the variations in atomic and ionic radii across a period and down a group.","level":"as_level"},{"key":"1.2.1","parent":"1.2","topic":"1.2","title":"Isotopes","description":"Define an isotope in terms of its numbers of protons and neutrons.","level":"as_level"},{"key":"1.2.2","parent":"1.2","topic":"1.2","title":"Isotopes","description":"Understand isotope notation using mass/nucleon number and atomic/proton number.","level":"as_level"},{"key":"1.2.3","parent":"1.2","topic":"1.2","title":"Isotopes","description":"Explain why isotopes of the same element have the same chemical properties.","level":"as_level"},{"key":"1.2.4","parent":"1.2","topic":"1.2","title":"Isotopes","description":"Explain why isotopes of the same element have different physical properties, limited to mass and density.","level":"as_level"},{"key":"1.3.1","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Understand shells, sub-shells, orbitals, principal quantum number n and ground state as applied to electronic configuration.","level":"as_level"},{"key":"1.3.2","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Describe the number of orbitals and maximum electrons in s, p and d sub-shells.","level":"as_level"},{"key":"1.3.3","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Describe the order of increasing sub-shell energy within the first three shells and the 4s and 4p sub-shells.","level":"as_level"},{"key":"1.3.4","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Describe electronic configurations by shell, sub-shell and orbital.","level":"as_level"},{"key":"1.3.5","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Explain electronic configurations in terms of electron energy and inter-electron repulsion.","level":"as_level"},{"key":"1.3.6","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Determine electronic configurations of atoms and ions from proton number and charge using full or shorthand notation.","level":"as_level"},{"key":"1.3.7","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Understand and use electrons-in-boxes notation.","level":"as_level"},{"key":"1.3.8","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Describe and sketch the shapes of s and p orbitals.","level":"as_level"},{"key":"1.3.9","parent":"1.3","topic":"1.3","title":"Electrons, energy levels and atomic orbitals","description":"Describe a free radical as a species with one or more unpaired electrons.","level":"as_level"},{"key":"1.4.1","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Define and use first ionisation energy, IE.","level":"as_level"},{"key":"1.4.2","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Construct equations representing first, second and subsequent ionisation energies.","level":"as_level"},{"key":"1.4.3","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Identify and explain trends in ionisation energies across periods and down groups.","level":"as_level"},{"key":"1.4.4","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Identify and explain variation in successive ionisation energies of an element.","level":"as_level"},{"key":"1.4.5","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Understand ionisation energies as arising from attraction between the nucleus and the outer electron.","level":"as_level"},{"key":"1.4.6","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Explain ionisation-energy factors using nuclear charge, atomic/ionic radius, shielding and spin-pair repulsion.","level":"as_level"},{"key":"1.4.7","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Deduce electronic configurations from successive ionisation-energy data.","level":"as_level"},{"key":"1.4.8","parent":"1.4","topic":"1.4","title":"Ionisation energy","description":"Deduce an element''s position in the Periodic Table from successive ionisation-energy data.","level":"as_level"},{"key":"2","parent":null,"topic":null,"title":"Atoms, molecules and stoichiometry","description":"Chemistry 9701 Topic 2: Atoms, molecules and stoichiometry","level":"as_level"},{"key":"2.1.1","parent":"2.1","topic":"2.1","title":"Relative masses of atoms and molecules","description":"Define the unified atomic mass unit as one twelfth of the mass of a carbon-12 atom.","level":"as_level"},{"key":"2.1.2","parent":"2.1","topic":"2.1","title":"Relative masses of atoms and molecules","description":"Define relative atomic mass, relative isotopic mass, relative molecular mass and relative formula mass in terms of the unified atomic mass unit.","level":"as_level"},{"key":"2.2.1","parent":"2.2","topic":"2.2","title":"The mole and the Avogadro constant","description":"Define and use the mole in terms of the Avogadro constant.","level":"as_level"},{"key":"2.3.1","parent":"2.3","topic":"2.3","title":"Formulas","description":"Write ionic-compound formulas from ionic charges and oxidation numbers, including predicting ionic charge from Periodic Table position and recalling the specified common ions.","level":"as_level"},{"key":"2.3.2","parent":"2.3","topic":"2.3","title":"Formulas","description":"Write and construct balanced equations, including ionic equations without spectator ions, and use appropriate state symbols.","level":"as_level"},{"key":"2.3.3","parent":"2.3","topic":"2.3","title":"Formulas","description":"Define and use empirical and molecular formula.","level":"as_level"},{"key":"2.3.4","parent":"2.3","topic":"2.3","title":"Formulas","description":"Understand and use anhydrous, hydrated and water of crystallisation.","level":"as_level"},{"key":"2.3.5","parent":"2.3","topic":"2.3","title":"Formulas","description":"Calculate empirical and molecular formulas from given data.","level":"as_level"},{"key":"2.4.1","parent":"2.4","topic":"2.4","title":"Reacting masses and volumes (of solutions and gases)","description":"Perform mole calculations involving reacting masses and percentage yield, gas volumes, solution volumes and concentrations, and limiting and excess reagents.","level":"as_level"},{"key":"2.4.2","parent":"2.4","topic":"2.4","title":"Reacting masses and volumes (of solutions and gases)","description":"Deduce stoichiometric relationships from mole calculations.","level":"as_level"},{"key":"3","parent":null,"topic":null,"title":"Chemical bonding","description":"Chemistry 9701 Topic 3: Chemical bonding","level":"as_level"},{"key":"3.1.1","parent":"3.1","topic":"3.1","title":"Electronegativity and bonding","description":"Define electronegativity as the power of an atom to attract electrons to itself.","level":"as_level"},{"key":"3.1.2","parent":"3.1","topic":"3.1","title":"Electronegativity and bonding","description":"Explain factors influencing electronegativity using nuclear charge, atomic radius and shielding by inner shells and sub-shells.","level":"as_level"},{"key":"3.1.3","parent":"3.1","topic":"3.1","title":"Electronegativity and bonding","description":"State and explain electronegativity trends across a period and down a group.","level":"as_level"},{"key":"3.1.4","parent":"3.1","topic":"3.1","title":"Electronegativity and bonding","description":"Use Pauling electronegativity differences to predict ionic or covalent bonding.","level":"as_level"},{"key":"3.2.1","parent":"3.2","topic":"3.2","title":"Ionic bonding","description":"Define ionic bonding as electrostatic attraction between oppositely charged ions.","level":"as_level"},{"key":"3.2.2","parent":"3.2","topic":"3.2","title":"Ionic bonding","description":"Describe ionic bonding using sodium chloride, magnesium oxide and calcium fluoride as examples.","level":"as_level"},{"key":"3.3.1","parent":"3.3","topic":"3.3","title":"Metallic bonding","description":"Define metallic bonding as electrostatic attraction between positive metal ions and delocalised electrons.","level":"as_level"},{"key":"3.4.1","parent":"3.4","topic":"3.4","title":"Covalent bonding and coordinate (dative covalent) bonding","description":"Define covalent bonding as electrostatic attraction between two nuclei and a shared pair of electrons, and describe covalent bonding in the specified molecules and expanded-octet examples.","level":"as_level"},{"key":"3.4.2","parent":"3.4","topic":"3.4","title":"Covalent bonding and coordinate (dative covalent) bonding","description":"Describe coordinate (dative covalent) bonding, including formation of NH4+ from ammonia and hydrogen chloride and bonding in Al2Cl6.","level":"as_level"},{"key":"3.4.3","parent":"3.4","topic":"3.4","title":"Covalent bonding and coordinate (dative covalent) bonding","description":"Describe sigma and pi bonds using orbital overlap, apply them to H2, C2H6, C2H4, HCN and N2, use sp/sp2/sp3 hybridisation, and relate bond energy and bond length to covalent reactivity.","level":"as_level"},{"key":"3.5.1","parent":"3.5","topic":"3.5","title":"Shapes of molecules","description":"State and explain molecular shapes and bond angles using VSEPR theory for the specified examples.","level":"as_level"},{"key":"3.5.2","parent":"3.5","topic":"3.5","title":"Shapes of molecules","description":"Predict shapes and bond angles in molecules and ions analogous to the specified VSEPR examples.","level":"as_level"},{"key":"3.6.1","parent":"3.6","topic":"3.6","title":"Intermolecular forces, electronegativity and bond properties","description":"Describe hydrogen bonding in molecules containing N-H and O-H groups and use it to explain anomalous properties of water.","level":"as_level"},{"key":"3.6.2","parent":"3.6","topic":"3.6","title":"Intermolecular forces, electronegativity and bond properties","description":"Use electronegativity to explain bond polarity and molecular dipole moments.","level":"as_level"},{"key":"3.6.3","parent":"3.6","topic":"3.6","title":"Intermolecular forces, electronegativity and bond properties","description":"Describe van der Waals'' forces, including instantaneous dipole-induced dipole and permanent dipole-permanent dipole forces, including hydrogen bonding.","level":"as_level"},{"key":"3.6.4","parent":"3.6","topic":"3.6","title":"Intermolecular forces, electronegativity and bond properties","description":"State that ionic, covalent and metallic bonding are generally stronger than intermolecular forces.","level":"as_level"},{"key":"3.7.1","parent":"3.7","topic":"3.7","title":"Dot-and-cross diagrams","description":"Use dot-and-cross diagrams to illustrate ionic, covalent and coordinate bonding, including species with expanded octets or odd numbers of electrons.","level":"as_level"},{"key":"4","parent":null,"topic":null,"title":"States of matter","description":"Chemistry 9701 Topic 4: States of matter","level":"as_level"},{"key":"4.1.1","parent":"4.1","topic":"4.1","title":"The gaseous state: ideal and real gases and pV = nRT","description":"Explain the origin of gas pressure in terms of collisions between gas molecules and container walls.","level":"as_level"},{"key":"4.1.2","parent":"4.1","topic":"4.1","title":"The gaseous state: ideal and real gases and pV = nRT","description":"Understand that an ideal gas has negligible particle volume and no intermolecular attractions.","level":"as_level"},{"key":"4.1.3","parent":"4.1","topic":"4.1","title":"The gaseous state: ideal and real gases and pV = nRT","description":"Use pV = nRT in calculations, including determination of relative molecular mass.","level":"as_level"},{"key":"4.2.1","parent":"4.2","topic":"4.2","title":"Bonding and structure","description":"Describe the lattice structures of giant ionic, simple molecular, giant molecular and giant metallic crystalline solids, using the specified examples.","level":"as_level"},{"key":"4.2.2","parent":"4.2","topic":"4.2","title":"Bonding and structure","description":"Describe, interpret and predict how structure and bonding affect melting point, boiling point, electrical conductivity and solubility.","level":"as_level"},{"key":"4.2.3","parent":"4.2","topic":"4.2","title":"Bonding and structure","description":"Deduce the structure and bonding of a substance from given information.","level":"as_level"},{"key":"5","parent":null,"topic":null,"title":"Chemical energetics","description":"Chemistry 9701 Topic 5: Chemical energetics","level":"as_level"},{"key":"5.1.1","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Understand that chemical reactions involve enthalpy changes and can be exothermic or endothermic.","level":"as_level"},{"key":"5.1.2","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Construct and interpret reaction pathway diagrams showing reaction enthalpy change and activation energy.","level":"as_level"},{"key":"5.1.3","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Define and use standard conditions and the specified enthalpy-change terms: reaction, formation, combustion and neutralisation.","level":"as_level"},{"key":"5.1.4","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Understand energy transfer during reactions as arising from breaking and making chemical bonds.","level":"as_level"},{"key":"5.1.5","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Use bond energies to calculate enthalpy changes of reaction.","level":"as_level"},{"key":"5.1.6","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Understand that some bond energies are exact while others are average values.","level":"as_level"},{"key":"5.1.7","parent":"5.1","topic":"5.1","title":"Enthalpy change, ΔH","description":"Calculate enthalpy changes from experimental results using q = mcΔT and ΔH = -mcΔT/n.","level":"as_level"},{"key":"5.2.1","parent":"5.2","topic":"5.2","title":"Hess’s law","description":"Apply Hess''s law to construct simple energy cycles.","level":"as_level"},{"key":"5.2.2","parent":"5.2","topic":"5.2","title":"Hess’s law","description":"Use energy cycles and relevant energy terms to calculate enthalpy changes that cannot be measured directly and to use bond-energy data.","level":"as_level"},{"key":"6","parent":null,"topic":null,"title":"Electrochemistry","description":"Chemistry 9701 Topic 6: Electrochemistry","level":"as_level"},{"key":"6.1.1","parent":"6.1","topic":"6.1","title":"Redox processes: electron transfer and changes in oxidation number (oxidation state)","description":"Calculate oxidation numbers of elements in compounds and ions.","level":"as_level"},{"key":"6.1.2","parent":"6.1","topic":"6.1","title":"Redox processes: electron transfer and changes in oxidation number (oxidation state)","description":"Use changes in oxidation numbers to help balance chemical equations.","level":"as_level"},{"key":"6.1.3","parent":"6.1","topic":"6.1","title":"Redox processes: electron transfer and changes in oxidation number (oxidation state)","description":"Explain and use redox, oxidation, reduction and disproportionation in terms of electron transfer and oxidation-number changes.","level":"as_level"},{"key":"6.1.4","parent":"6.1","topic":"6.1","title":"Redox processes: electron transfer and changes in oxidation number (oxidation state)","description":"Explain and use oxidising agent and reducing agent.","level":"as_level"},{"key":"6.1.5","parent":"6.1","topic":"6.1","title":"Redox processes: electron transfer and changes in oxidation number (oxidation state)","description":"Use Roman numerals to indicate oxidation-number magnitude.","level":"as_level"},{"key":"7","parent":null,"topic":null,"title":"Equilibria","description":"Chemistry 9701 Topic 7: Equilibria","level":"as_level"},{"key":"7.1.1","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Understand reversible reactions, dynamic equilibrium as equal forward and reverse rates with constant concentrations, and the need for a closed system.","level":"as_level"},{"key":"7.1.2","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Define Le Chatelier''s principle and use it to deduce qualitative equilibrium shifts caused by temperature, concentration, pressure or catalysts.","level":"as_level"},{"key":"7.1.3","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Deduce Kc expressions and carry out Kc calculations.","level":"as_level"},{"key":"7.1.4","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Use mole fraction and partial pressure and deduce Kp expressions.","level":"as_level"},{"key":"7.1.5","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Use Kc and Kp expressions for calculations without requiring quadratic equations.","level":"as_level"},{"key":"7.1.6","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Calculate equilibrium quantities from appropriate data.","level":"as_level"},{"key":"7.1.7","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"State whether temperature, concentration, pressure or a catalyst changes the equilibrium constant.","level":"as_level"},{"key":"7.1.8","parent":"7.1","topic":"7.1","title":"Chemical equilibria: reversible reactions, dynamic equilibrium","description":"Describe and explain Haber-process and Contact-process conditions as applications of dynamic equilibrium and Le Chatelier''s principle.","level":"as_level"},{"key":"7.2.1","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"State the specified common acids and their formulas.","level":"as_level"},{"key":"7.2.2","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"State the specified common alkalis and their formulas.","level":"as_level"},{"key":"7.2.3","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Describe the Brønsted-Lowry theory of acids and bases.","level":"as_level"},{"key":"7.2.4","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Describe strong acids/bases as fully dissociated and weak acids/bases as partially dissociated in aqueous solution.","level":"as_level"},{"key":"7.2.5","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Relate pH 7 to neutral water and distinguish acidic and alkaline solution pH ranges.","level":"as_level"},{"key":"7.2.6","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Explain qualitative differences between strong and weak acids, including reaction with a reactive metal and differences in pH measured by pH meter, universal indicator or conductivity.","level":"as_level"},{"key":"7.2.7","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Understand neutralisation as H+(aq) and OH-(aq) forming H2O(l).","level":"as_level"},{"key":"7.2.8","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Understand that salts are formed in neutralisation reactions.","level":"as_level"},{"key":"7.2.9","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Sketch pH titration curves for combinations of strong and weak acids with strong and weak alkalis.","level":"as_level"},{"key":"7.2.10","parent":"7.2","topic":"7.2","title":"Brønsted–Lowry theory of acids and bases","description":"Select suitable indicators for acid-alkali titrations from given data.","level":"as_level"},{"key":"8","parent":null,"topic":null,"title":"Reaction kinetics","description":"Chemistry 9701 Topic 8: Reaction kinetics","level":"as_level"},{"key":"8.1.1","parent":"8.1","topic":"8.1","title":"Rate of reaction","description":"Explain and use rate of reaction, collision frequency, effective collisions and non-effective collisions.","level":"as_level"},{"key":"8.1.2","parent":"8.1","topic":"8.1","title":"Rate of reaction","description":"Explain qualitatively how concentration and pressure affect reaction rate through the frequency of effective collisions.","level":"as_level"},{"key":"8.1.3","parent":"8.1","topic":"8.1","title":"Rate of reaction","description":"Use experimental data to calculate reaction rate.","level":"as_level"},{"key":"8.2.1","parent":"8.2","topic":"8.2","title":"Effect of temperature on reaction rates and the concept of activation energy","description":"Define activation energy, EA, as the minimum energy required for an effective collision.","level":"as_level"},{"key":"8.2.2","parent":"8.2","topic":"8.2","title":"Effect of temperature on reaction rates and the concept of activation energy","description":"Sketch and use the Boltzmann distribution to explain the significance of activation energy.","level":"as_level"},{"key":"8.2.3","parent":"8.2","topic":"8.2","title":"Effect of temperature on reaction rates and the concept of activation energy","description":"Explain qualitatively how temperature changes reaction rate using the Boltzmann distribution and frequency of effective collisions.","level":"as_level"},{"key":"8.3.1","parent":"8.3","topic":"8.3","title":"Homogeneous and heterogeneous catalysts","description":"Explain catalyst and catalysis, including that a catalyst provides a different mechanism with lower activation energy, the Boltzmann-distribution explanation, and reaction-pathway diagrams with and without an effective catalyst.","level":"as_level"},{"key":"9","parent":null,"topic":null,"title":"The Periodic Table: chemical periodicity","description":"Chemistry 9701 Topic 9: The Periodic Table: chemical periodicity","level":"as_level"},{"key":"9.1.1","parent":"9.1","topic":"9.1","title":"Periodicity of physical properties of the elements in Period 3","description":"Describe qualitative periodic variations in atomic radius, ionic radius, melting point and electrical conductivity across Period 3.","level":"as_level"},{"key":"9.1.2","parent":"9.1","topic":"9.1","title":"Periodicity of physical properties of the elements in Period 3","description":"Explain melting-point and electrical-conductivity variation in terms of structure and bonding.","level":"as_level"},{"key":"9.2.1","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Describe and write equations for Period 3 element reactions with oxygen, chlorine and water where specified.","level":"as_level"},{"key":"9.2.2","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"State and explain oxidation-number variation in specified Period 3 oxides and chlorides using outer-shell electrons.","level":"as_level"},{"key":"9.2.3","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Describe and write equations for reactions of specified Period 3 oxides with water and identify likely solution pH.","level":"as_level"},{"key":"9.2.4","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Describe, explain and write equations for acid-base behaviour of specified Period 3 oxides and hydroxides, including relevant amphoteric behaviour.","level":"as_level"},{"key":"9.2.5","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Describe, explain and write equations for reactions of specified Period 3 chlorides with water and identify likely solution pH.","level":"as_level"},{"key":"9.2.6","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Explain trends in Period 3 chemical properties using bonding and electronegativity.","level":"as_level"},{"key":"9.2.7","parent":"9.2","topic":"9.2","title":"Periodicity of chemical properties of the elements in Period 3","description":"Suggest bonding types in specified chlorides and oxides from chemical and physical properties.","level":"as_level"},{"key":"9.3.1","parent":"9.3","topic":"9.3","title":"Chemical periodicity of other elements","description":"Predict characteristic properties of an element in a given group using chemical periodicity.","level":"as_level"},{"key":"9.3.2","parent":"9.3","topic":"9.3","title":"Chemical periodicity of other elements","description":"Deduce the nature, possible Periodic Table position and identity of unknown elements from physical and chemical property data.","level":"as_level"},{"key":"10","parent":null,"topic":null,"title":"Group 2","description":"Chemistry 9701 Topic 10: Group 2","level":"as_level"},{"key":"10.1.1","parent":"10.1","topic":"10.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Describe and write equations for Group 2 elements reacting with oxygen, water and dilute hydrochloric and sulfuric acids.","level":"as_level"},{"key":"10.1.2","parent":"10.1","topic":"10.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Describe and write equations for Group 2 oxides, hydroxides and carbonates reacting with water and dilute hydrochloric and sulfuric acids.","level":"as_level"},{"key":"10.1.3","parent":"10.1","topic":"10.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Describe and write equations for thermal decomposition of Group 2 nitrates and carbonates, including the trend in thermal stability.","level":"as_level"},{"key":"10.1.4","parent":"10.1","topic":"10.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Describe and predict trends in physical and chemical properties of the Group 2 elements and their compounds.","level":"as_level"},{"key":"10.1.5","parent":"10.1","topic":"10.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"State the variation in solubilities of Group 2 hydroxides and sulfates.","level":"as_level"},{"key":"11","parent":null,"topic":null,"title":"Group 17","description":"Chemistry 9701 Topic 11: Group 17","level":"as_level"},{"key":"11.1.1","parent":"11.1","topic":"11.1","title":"Physical properties of the Group 17 elements","description":"Describe the colours and volatility trend of chlorine, bromine and iodine.","level":"as_level"},{"key":"11.1.2","parent":"11.1","topic":"11.1","title":"Physical properties of the Group 17 elements","description":"Describe and explain the trend in bond strength of halogen molecules.","level":"as_level"},{"key":"11.1.3","parent":"11.1","topic":"11.1","title":"Physical properties of the Group 17 elements","description":"Interpret volatility in terms of instantaneous dipole-induced dipole forces.","level":"as_level"},{"key":"11.2.1","parent":"11.2","topic":"11.2","title":"The chemical properties of the halogen elements and the hydrogen halides","description":"Describe relative reactivity of halogen elements as oxidising agents.","level":"as_level"},{"key":"11.2.2","parent":"11.2","topic":"11.2","title":"The chemical properties of the halogen elements and the hydrogen halides","description":"Describe reactions of halogen elements with hydrogen and explain their relative reactivity.","level":"as_level"},{"key":"11.2.3","parent":"11.2","topic":"11.2","title":"The chemical properties of the halogen elements and the hydrogen halides","description":"Describe relative thermal stabilities of hydrogen halides and explain them using bond strengths.","level":"as_level"},{"key":"11.3.1","parent":"11.3","topic":"11.3","title":"Some reactions of the halide ions","description":"Describe relative reactivity of halide ions as reducing agents.","level":"as_level"},{"key":"11.3.2","parent":"11.3","topic":"11.3","title":"Some reactions of the halide ions","description":"Describe and explain halide-ion reactions with aqueous silver ions followed by aqueous ammonia and with concentrated sulfuric acid, including balanced equations.","level":"as_level"},{"key":"11.4.1","parent":"11.4","topic":"11.4","title":"The reactions of chlorine","description":"Describe and interpret chlorine reactions with cold and hot aqueous sodium hydroxide in terms of oxidation-number changes and identify them as disproportionation.","level":"as_level"},{"key":"11.4.2","parent":"11.4","topic":"11.4","title":"The reactions of chlorine","description":"Explain, including with an equation, the use of chlorine in water purification, including formation of HOCl and ClO- active species.","level":"as_level"},{"key":"12","parent":null,"topic":null,"title":"Nitrogen and sulfur","description":"Chemistry 9701 Topic 12: Nitrogen and sulfur","level":"as_level"},{"key":"12.1.1","parent":"12.1","topic":"12.1","title":"Nitrogen and sulfur","description":"Explain nitrogen''s low reactivity using triple-bond strength and lack of polarity.","level":"as_level"},{"key":"12.1.2","parent":"12.1","topic":"12.1","title":"Nitrogen and sulfur","description":"Describe and explain ammonia basicity, ammonium-ion structure and formation, and displacement of ammonia from ammonium salts using acid-base reactions.","level":"as_level"},{"key":"12.1.3","parent":"12.1","topic":"12.1","title":"Nitrogen and sulfur","description":"State and explain natural and man-made occurrences of nitrogen oxides and their catalytic removal from internal-combustion-engine exhaust.","level":"as_level"},{"key":"12.1.4","parent":"12.1","topic":"12.1","title":"Nitrogen and sulfur","description":"Understand that NO and NO2 can react with unburned hydrocarbons to form PAN, a component of photochemical smog.","level":"as_level"},{"key":"12.1.5","parent":"12.1","topic":"12.1","title":"Nitrogen and sulfur","description":"Describe the role of NO and NO2 in acid-rain formation, including catalytic oxidation of atmospheric sulfur dioxide.","level":"as_level"},{"key":"13","parent":null,"topic":null,"title":"An introduction to AS Level organic chemistry","description":"Chemistry 9701 Topic 13: An introduction to AS Level organic chemistry","level":"as_level"},{"key":"13.1.1","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Define hydrocarbons as compounds containing carbon and hydrogen only.","level":"as_level"},{"key":"13.1.2","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Recognise alkanes as simple hydrocarbons without a functional group.","level":"as_level"},{"key":"13.1.3","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Understand that functional groups largely determine the physical and chemical properties of the listed organic classes.","level":"as_level"},{"key":"13.1.4","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Interpret general, structural, displayed and skeletal formulae for the specified organic classes.","level":"as_level"},{"key":"13.1.5","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Use systematic nomenclature for simple aliphatic compounds with the stated carbon-number limits.","level":"as_level"},{"key":"13.1.6","parent":"13.1","topic":"13.1","title":"Formulas, functional groups and the naming of organic compounds","description":"Deduce molecular and/or empirical formulae from structural, displayed or skeletal formulae.","level":"as_level"},{"key":"13.2.1","parent":"13.2","topic":"13.2","title":"Characteristic organic reactions","description":"Use terminology for homologous series, saturated/unsaturated compounds, homolytic/heterolytic fission, radicals, nucleophiles, electrophiles, addition, substitution, elimination, hydrolysis, condensation, oxidation and reduction.","level":"as_level"},{"key":"13.2.2","parent":"13.2","topic":"13.2","title":"Characteristic organic reactions","description":"Use terminology for free-radical substitution, electrophilic addition, nucleophilic substitution and nucleophilic addition mechanisms, including curly-arrow electron-pair notation.","level":"as_level"},{"key":"13.3.1","parent":"13.3","topic":"13.3","title":"Shapes of organic molecules; σ and π bonds","description":"Classify organic molecules as straight-chain, branched or cyclic.","level":"as_level"},{"key":"13.3.2","parent":"13.3","topic":"13.3","title":"Shapes of organic molecules; σ and π bonds","description":"Explain molecular shapes and bond angles for sp, sp² and sp³ hybridised atoms.","level":"as_level"},{"key":"13.3.3","parent":"13.3","topic":"13.3","title":"Shapes of organic molecules; σ and π bonds","description":"Describe σ and π bond arrangements for sp, sp² and sp³ hybridisation.","level":"as_level"},{"key":"13.3.4","parent":"13.3","topic":"13.3","title":"Shapes of organic molecules; σ and π bonds","description":"Use planar correctly for appropriate organic molecules such as ethene.","level":"as_level"},{"key":"13.4.1","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Distinguish chain, positional and functional-group structural isomerism.","level":"as_level"},{"key":"13.4.2","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Distinguish geometrical and optical stereoisomerism.","level":"as_level"},{"key":"13.4.3","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Explain cis/trans isomerism in alkenes through restricted rotation about π bonds.","level":"as_level"},{"key":"13.4.4","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Explain chiral centres and enantiomers.","level":"as_level"},{"key":"13.4.5","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Identify chiral centres and cis/trans isomerism from structural formulae, including cyclic compounds.","level":"as_level"},{"key":"13.4.6","parent":"13.4","topic":"13.4","title":"Isomerism: structural isomerism and stereoisomerism","description":"Deduce possible isomers from a known molecular formula.","level":"as_level"},{"key":"14","parent":null,"topic":null,"title":"Hydrocarbons","description":"Chemistry 9701 Topic 14: Hydrocarbons","level":"as_level"},{"key":"14.1.1","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Recall alkane preparation by alkene hydrogenation and cracking.","level":"as_level"},{"key":"14.1.2","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Describe complete/incomplete combustion and free-radical substitution with chlorine/bromine under UV light.","level":"as_level"},{"key":"14.1.3","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Explain initiation, propagation and termination in free-radical substitution.","level":"as_level"},{"key":"14.1.4","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Explain cracking as a route to useful lower-relative-mass alkanes and alkenes.","level":"as_level"},{"key":"14.1.5","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Explain low alkane reactivity using strong, relatively non-polar C–H bonds.","level":"as_level"},{"key":"14.1.6","parent":"14.1","topic":"14.1","title":"Alkanes","description":"Recognise combustion pollutants and catalytic removal.","level":"as_level"},{"key":"14.2.1","parent":"14.2","topic":"14.2","title":"Alkenes","description":"Recall alkene preparation by elimination, dehydration and cracking.","level":"as_level"},{"key":"14.2.2","parent":"14.2","topic":"14.2","title":"Alkenes","description":"Describe alkene additions with H₂, steam, HX and X₂, specified oxidations and addition polymerisation.","level":"as_level"},{"key":"14.2.3","parent":"14.2","topic":"14.2","title":"Alkenes","description":"Use aqueous bromine to test for C=C.","level":"as_level"},{"key":"14.2.4","parent":"14.2","topic":"14.2","title":"Alkenes","description":"Explain electrophilic-addition mechanisms using bromine/ethene and HBr/propene.","level":"as_level"},{"key":"14.2.5","parent":"14.2","topic":"14.2","title":"Alkenes","description":"Explain alkyl inductive effects on carbocation stability and Markovnikov addition.","level":"as_level"},{"key":"15","parent":null,"topic":null,"title":"Halogen compounds","description":"Chemistry 9701 Topic 15: Halogen compounds","level":"as_level"},{"key":"15.1.1","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Recall halogenoalkane preparation by radical substitution, alkene addition and alcohol substitution.","level":"as_level"},{"key":"15.1.2","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Classify halogenoalkanes as primary, secondary or tertiary.","level":"as_level"},{"key":"15.1.3","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Describe nucleophilic substitution with OH⁻, CN⁻, NH₃ and aqueous silver nitrate.","level":"as_level"},{"key":"15.1.4","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Describe ethanolic-OH elimination to form alkenes.","level":"as_level"},{"key":"15.1.5","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Explain SN1 and SN2 mechanisms and alkyl inductive effects.","level":"as_level"},{"key":"15.1.6","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Relate halogenoalkane class to predominant SN1/SN2 pathway.","level":"as_level"},{"key":"15.1.7","parent":"15.1","topic":"15.1","title":"Halogenoalkanes","description":"Explain reactivity differences using C–X bond strength and silver-nitrate reactions.","level":"as_level"},{"key":"16","parent":null,"topic":null,"title":"Hydroxy compounds","description":"Chemistry 9701 Topic 16: Hydroxy compounds","level":"as_level"},{"key":"16.1.1","parent":"16.1","topic":"16.1","title":"Alcohols","description":"Recall routes to alcohols from alkenes, halogenoalkanes, carbonyl compounds, carboxylic acids and esters.","level":"as_level"},{"key":"16.1.2","parent":"16.1","topic":"16.1","title":"Alcohols","description":"Describe alcohol combustion, substitution, reaction with sodium, oxidation, dehydration and ester formation.","level":"as_level"},{"key":"16.1.3","parent":"16.1","topic":"16.1","title":"Alcohols","description":"Classify primary, secondary and tertiary alcohols and use oxidation behaviour to distinguish them.","level":"as_level"},{"key":"16.1.4","parent":"16.1","topic":"16.1","title":"Alcohols","description":"Identify a CH3CH(OH)– group with the alkaline iodine test.","level":"as_level"},{"key":"16.1.5","parent":"16.1","topic":"16.1","title":"Alcohols","description":"Explain alcohol acidity relative to water.","level":"as_level"},{"key":"17","parent":null,"topic":null,"title":"Carbonyl compounds","description":"Chemistry 9701 Topic 17: Carbonyl compounds","level":"as_level"},{"key":"17.1.1","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Recall aldehyde/ketone preparation by oxidation of primary/secondary alcohols.","level":"as_level"},{"key":"17.1.2","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Describe carbonyl reduction and hydroxynitrile formation with HCN.","level":"as_level"},{"key":"17.1.3","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Explain nucleophilic addition of HCN to carbonyl compounds.","level":"as_level"},{"key":"17.1.4","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Use 2,4-DNPH to detect carbonyl compounds.","level":"as_level"},{"key":"17.1.5","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Distinguish aldehydes and ketones using Fehling''s/Tollens'' tests and oxidation.","level":"as_level"},{"key":"17.1.6","parent":"17.1","topic":"17.1","title":"Aldehydes and ketones","description":"Identify CH3CO– groups using the alkaline iodine test.","level":"as_level"},{"key":"18","parent":null,"topic":null,"title":"Carboxylic acids and derivatives","description":"Chemistry 9701 Topic 18: Carboxylic acids and derivatives","level":"as_level"},{"key":"18.1.1","parent":"18.1","topic":"18.1","title":"Carboxylic acids","description":"Recall carboxylic-acid preparation by oxidation and nitrile/ester hydrolysis.","level":"as_level"},{"key":"18.1.2","parent":"18.1","topic":"18.1","title":"Carboxylic acids","description":"Describe reactions with reactive metals, alkalis, carbonates, alcohols and LiAlH4.","level":"as_level"},{"key":"18.2.1","parent":"18.2","topic":"18.2","title":"Esters","description":"Recall ester formation from alcohol and carboxylic acid with concentrated H2SO4 catalyst.","level":"as_level"},{"key":"18.2.2","parent":"18.2","topic":"18.2","title":"Esters","description":"Describe acid- and alkali-catalysed ester hydrolysis on heating.","level":"as_level"},{"key":"19","parent":null,"topic":null,"title":"Nitrogen compounds","description":"Chemistry 9701 Topic 19: Nitrogen compounds","level":"as_level"},{"key":"19.1.1","parent":"19.1","topic":"19.1","title":"Primary amines","description":"Recall primary-amine preparation from halogenoalkanes using ammonia under pressure.","level":"as_level"},{"key":"19.2.1","parent":"19.2","topic":"19.2","title":"Nitriles and hydroxynitriles","description":"Recall nitrile formation from halogenoalkanes using ethanolic cyanide.","level":"as_level"},{"key":"19.2.2","parent":"19.2","topic":"19.2","title":"Nitriles and hydroxynitriles","description":"Recall hydroxynitrile formation from carbonyl compounds with HCN/cyanide catalyst.","level":"as_level"},{"key":"19.2.3","parent":"19.2","topic":"19.2","title":"Nitriles and hydroxynitriles","description":"Describe nitrile hydrolysis to carboxylic acids.","level":"as_level"},{"key":"20","parent":null,"topic":null,"title":"Polymerisation","description":"Chemistry 9701 Topic 20: Polymerisation","level":"as_level"},{"key":"20.1.1","parent":"20.1","topic":"20.1","title":"Addition polymerisation","description":"Describe addition polymerisation using poly(ethene) and PVC.","level":"as_level"},{"key":"20.1.2","parent":"20.1","topic":"20.1","title":"Addition polymerisation","description":"Deduce an addition-polymer repeat unit from a monomer.","level":"as_level"},{"key":"20.1.3","parent":"20.1","topic":"20.1","title":"Addition polymerisation","description":"Identify monomers from a polymer section.","level":"as_level"},{"key":"20.1.4","parent":"20.1","topic":"20.1","title":"Addition polymerisation","description":"Explain disposal difficulties of poly(alkene)s.","level":"as_level"},{"key":"21","parent":null,"topic":null,"title":"Organic synthesis","description":"Chemistry 9701 Topic 21: Organic synthesis","level":"as_level"},{"key":"21.1.1","parent":"21.1","topic":"21.1","title":"Organic synthesis","description":"For multi-functional molecules, identify functional groups and predict properties/reactions.","level":"as_level"},{"key":"21.1.2","parent":"21.1","topic":"21.1","title":"Organic synthesis","description":"Devise multi-step synthetic routes using syllabus reactions.","level":"as_level"},{"key":"21.1.3","parent":"21.1","topic":"21.1","title":"Organic synthesis","description":"Analyse a synthesis by reaction type, reagents and possible by-products.","level":"as_level"},{"key":"22","parent":null,"topic":null,"title":"Analytical techniques","description":"Chemistry 9701 Topic 22: Analytical techniques","level":"as_level"},{"key":"22.1.1","parent":"22.1","topic":"22.1","title":"Infrared spectroscopy","description":"Analyse a simple IR spectrum to identify required functional groups.","level":"as_level"},{"key":"22.2.1","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Interpret mass spectra using m/e and isotope abundance.","level":"as_level"},{"key":"22.2.2","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Calculate relative atomic mass from isotope data or a mass spectrum.","level":"as_level"},{"key":"22.2.3","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Deduce organic molecular mass from the molecular-ion peak.","level":"as_level"},{"key":"22.2.4","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Suggest simple fragment identities.","level":"as_level"},{"key":"22.2.5","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Use the [M+1]+ peak to estimate carbon number.","level":"as_level"},{"key":"22.2.6","parent":"22.2","topic":"22.2","title":"Mass spectrometry","description":"Use [M+2]+ patterns to detect bromine/chlorine.","level":"as_level"},{"key":"23","parent":null,"topic":null,"title":"Chemical energetics","description":"Chemistry 9701 Topic 23: Chemical energetics","level":"a_level"},{"key":"23.1.1","parent":"23.1","topic":"23.1","title":"Lattice energy and Born–Haber cycles","description":"Define atomisation enthalpy and lattice energy.","level":"a_level"},{"key":"23.1.2","parent":"23.1","topic":"23.1","title":"Lattice energy and Born–Haber cycles","description":"Define first electron affinity and explain its factors and Group 16/17 trends.","level":"a_level"},{"key":"23.1.3","parent":"23.1","topic":"23.1","title":"Lattice energy and Born–Haber cycles","description":"Construct and use Born–Haber cycles.","level":"a_level"},{"key":"23.1.4","parent":"23.1","topic":"23.1","title":"Lattice energy and Born–Haber cycles","description":"Perform Born–Haber calculations.","level":"a_level"},{"key":"23.1.5","parent":"23.1","topic":"23.1","title":"Lattice energy and Born–Haber cycles","description":"Explain ionic-charge and ionic-radius effects on lattice-energy magnitude.","level":"a_level"},{"key":"23.2.1","parent":"23.2","topic":"23.2","title":"Enthalpies of solution and hydration","description":"Define hydration and solution enthalpy changes.","level":"a_level"},{"key":"23.2.2","parent":"23.2","topic":"23.2","title":"Enthalpies of solution and hydration","description":"Construct/use cycles linking solution enthalpy, lattice energy and hydration enthalpy.","level":"a_level"},{"key":"23.2.3","parent":"23.2","topic":"23.2","title":"Enthalpies of solution and hydration","description":"Calculate using these cycles.","level":"a_level"},{"key":"23.2.4","parent":"23.2","topic":"23.2","title":"Enthalpies of solution and hydration","description":"Explain ionic-charge and ionic-radius effects on hydration enthalpy.","level":"a_level"},{"key":"23.3.1","parent":"23.3","topic":"23.3","title":"Entropy change, ΔS","description":"Define entropy as possible arrangements of particles and their energy.","level":"a_level"},{"key":"23.3.2","parent":"23.3","topic":"23.3","title":"Entropy change, ΔS","description":"Predict/explain entropy-change signs for state changes, temperature changes and changes in gaseous-molecule number.","level":"a_level"},{"key":"23.3.3","parent":"23.3","topic":"23.3","title":"Entropy change, ΔS","description":"Calculate reaction entropy from standard entropy data.","level":"a_level"},{"key":"23.4.1","parent":"23.4","topic":"23.4","title":"Gibbs free energy change, ΔG","description":"Use ΔG° = ΔH° − TΔS°.","level":"a_level"},{"key":"23.4.2","parent":"23.4","topic":"23.4","title":"Gibbs free energy change, ΔG","description":"Calculate Gibbs free-energy changes.","level":"a_level"},{"key":"23.4.3","parent":"23.4","topic":"23.4","title":"Gibbs free energy change, ΔG","description":"Use the sign of ΔG to assess feasibility.","level":"a_level"},{"key":"23.4.4","parent":"23.4","topic":"23.4","title":"Gibbs free energy change, ΔG","description":"Predict temperature effects on feasibility.","level":"a_level"},{"key":"24","parent":null,"topic":null,"title":"Electrochemistry","description":"Chemistry 9701 Topic 24: Electrochemistry","level":"a_level"},{"key":"24.1.1","parent":"24.1","topic":"24.1","title":"Electrolysis","description":"Predict electrolysis products from electrolyte state, electrode potential/redox position and concentration.","level":"a_level"},{"key":"24.1.2","parent":"24.1","topic":"24.1","title":"Electrolysis","description":"Use F = Le.","level":"a_level"},{"key":"24.1.3","parent":"24.1","topic":"24.1","title":"Electrolysis","description":"Calculate charge using Q = It and calculate mass/volume liberated.","level":"a_level"},{"key":"24.1.4","parent":"24.1","topic":"24.1","title":"Electrolysis","description":"Describe an electrolytic determination of Avogadro''s constant.","level":"a_level"},{"key":"24.2.1","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Define standard electrode-reduction and standard cell potentials.","level":"a_level"},{"key":"24.2.2","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Describe the standard hydrogen electrode.","level":"a_level"},{"key":"24.2.3","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Describe measurement of standard electrode potentials.","level":"a_level"},{"key":"24.2.4","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Calculate standard cell potentials.","level":"a_level"},{"key":"24.2.5","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Use cell potentials for polarity, electron flow and feasibility.","level":"a_level"},{"key":"24.2.6","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Compare oxidising/reducing strengths using E°.","level":"a_level"},{"key":"24.2.7","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Construct redox equations from half-equations.","level":"a_level"},{"key":"24.2.8","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Predict concentration effects on electrode potential.","level":"a_level"},{"key":"24.2.9","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Use the Nernst equation quantitatively.","level":"a_level"},{"key":"24.2.10","parent":"24.2","topic":"24.2","title":"Standard electrode potentials E°; standard cell potentials E°cell and the Nernst equation","description":"Use ΔG° = −nFE°cell.","level":"a_level"},{"key":"25","parent":null,"topic":null,"title":"Equilibria","description":"Chemistry 9701 Topic 25: Equilibria","level":"a_level"},{"key":"25.1.1","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Use conjugate-acid/base terminology and identify pairs.","level":"a_level"},{"key":"25.1.2","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Use pH, Ka, pKa and Kw mathematically within syllabus limits.","level":"a_level"},{"key":"25.1.3","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Calculate [H+] and pH for strong acids, strong alkalis and weak acids.","level":"a_level"},{"key":"25.1.4","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Define, prepare and explain buffer solutions.","level":"a_level"},{"key":"25.1.5","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Describe buffer uses including bicarbonate in blood.","level":"a_level"},{"key":"25.1.6","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Calculate buffer pH.","level":"a_level"},{"key":"25.1.7","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Define and write Ksp expressions.","level":"a_level"},{"key":"25.1.8","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Calculate Ksp or concentrations.","level":"a_level"},{"key":"25.1.9","parent":"25.1","topic":"25.1","title":"Acids and bases","description":"Use the common-ion effect and perform related Ksp calculations.","level":"a_level"},{"key":"25.2.1","parent":"25.2","topic":"25.2","title":"Partition coefficients","description":"Define Kpc.","level":"a_level"},{"key":"25.2.2","parent":"25.2","topic":"25.2","title":"Partition coefficients","description":"Calculate/use Kpc when the solute remains in the same physical state in both solvents.","level":"a_level"},{"key":"25.2.3","parent":"25.2","topic":"25.2","title":"Partition coefficients","description":"Explain Kpc in terms of solute/solvent polarity.","level":"a_level"},{"key":"26","parent":null,"topic":null,"title":"Reaction kinetics","description":"Chemistry 9701 Topic 26: Reaction kinetics","level":"a_level"},{"key":"26.1.1","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Use rate-equation terminology including order, overall order, k, half-life, rate-determining step and intermediate.","level":"a_level"},{"key":"26.1.2","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Use rate = k[A]^m[B]^n for orders 0,1,2 and deduce order from graphs/data.","level":"a_level"},{"key":"26.1.3","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Interpret concentration-time and rate-concentration graphs and calculate initial rates.","level":"a_level"},{"key":"26.1.4","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Construct rate equations.","level":"a_level"},{"key":"26.1.5","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Use first-order half-life.","level":"a_level"},{"key":"26.1.6","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Calculate k from initial rates or k = 0.693/t½.","level":"a_level"},{"key":"26.1.7","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Relate multi-step mechanisms to rate equations and identify intermediates/catalysts/rate-determining steps.","level":"a_level"},{"key":"26.1.8","parent":"26.1","topic":"26.1","title":"Simple rate equations, orders of reaction and rate constants","description":"Explain temperature effects on k and rate.","level":"a_level"},{"key":"26.2.1","parent":"26.2","topic":"26.2","title":"Homogeneous and heterogeneous catalysts","description":"Distinguish homogeneous and heterogeneous catalysis.","level":"a_level"},{"key":"26.2.2","parent":"26.2","topic":"26.2","title":"Homogeneous and heterogeneous catalysts","description":"Explain heterogeneous catalysis through adsorption, bond weakening and desorption.","level":"a_level"},{"key":"26.2.3","parent":"26.2","topic":"26.2","title":"Homogeneous and heterogeneous catalysts","description":"Explain homogeneous catalysis through catalyst use and regeneration.","level":"a_level"},{"key":"27","parent":null,"topic":null,"title":"Group 2","description":"Chemistry 9701 Topic 27: Group 2","level":"a_level"},{"key":"27.1.1","parent":"27.1","topic":"27.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Explain Group 2 thermal-stability trends for nitrates/carbonates using ionic-radius polarisation.","level":"a_level"},{"key":"27.1.2","parent":"27.1","topic":"27.1","title":"Similarities and trends in the properties of the Group 2 metals, magnesium to barium, and their compounds","description":"Explain hydroxide/sulfate solubility and solution-enthalpy trends using hydration enthalpy and lattice energy.","level":"a_level"},{"key":"28","parent":null,"topic":null,"title":"Chemistry of transition elements","description":"Chemistry 9701 Topic 28: Chemistry of transition elements","level":"a_level"},{"key":"28.1.1","parent":"28.1","topic":"28.1","title":"General physical and chemical properties of the first row of transition elements, titanium to copper","description":"Define transition elements using incomplete d orbitals in stable ions.","level":"a_level"},{"key":"28.1.2","parent":"28.1","topic":"28.1","title":"General physical and chemical properties of the first row of transition elements, titanium to copper","description":"Sketch 3dxy and 3dz² orbitals.","level":"a_level"},{"key":"28.1.3","parent":"28.1","topic":"28.1","title":"General physical and chemical properties of the first row of transition elements, titanium to copper","description":"Describe variable oxidation states, catalysis, complex ions and coloured compounds.","level":"a_level"},{"key":"28.1.4","parent":"28.1","