l":"a_level"},{"key":"37.4.1","parent":"37.4","topic":"37.4","title":"Proton NMR spectroscopy","description":"Interpret proton NMR using chemical shifts, peak areas, splitting and possible structures.","level":"a_level"},{"key":"37.4.2","parent":"37.4","topic":"37.4","title":"Proton NMR spectroscopy","description":"Predict proton shifts and splitting.","level":"a_level"},{"key":"37.4.3","parent":"37.4","topic":"37.4","title":"Proton NMR spectroscopy","description":"Describe TMS as chemical-shift standard.","level":"a_level"},{"key":"37.4.4","parent":"37.4","topic":"37.4","title":"Proton NMR spectroscopy","description":"Explain use of deuterated solvents.","level":"a_level"},{"key":"37.4.5","parent":"37.4","topic":"37.4","title":"Proton NMR spectroscopy","description":"Identify O–H/N–H protons by D2O exchange.","level":"a_level"},{"key":"37.5.1","parent":"37.5","topic":"37.5","title":"Combined analytical techniques","description":"Use combined chromatography, IR, mass-spectrometry and NMR evidence to identify or distinguish simple organic structures.","level":"a_level"}]'::jsonb) as x(key text,parent text,topic text,title text,description text,level text);
