ured-cambridge-dataset","section":"1","outcomeIndex":7}},{"level":"as_level","kind":"topic","knowledge_key":"topic|1.2","title":"Isotopes","content":"1.2 Isotopes","topic":"1.2","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"1"}},{"level":"as_level","kind":"content_scope","knowledge_key":"scope|1.2","title":"Isotopes","content":"Atomic structure: Isotopes. This subsection is part of the AS Level Chemistry 9701 syllabus.","topic":"1.2","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"1"}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.2|1","title":"Isotopes: outcome 1","content":"Define an isotope in terms of its numbers of protons and neutrons.","topic":"1.2","objectives":["1.2.1"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":1}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.2|2","title":"Isotopes: outcome 2","content":"Understand isotope notation using mass/nucleon number and atomic/proton number.","topic":"1.2","objectives":["1.2.2"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":2}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.2|3","title":"Isotopes: outcome 3","content":"Explain why isotopes of the same element have the same chemical properties.","topic":"1.2","objectives":["1.2.3"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":3}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.2|4","title":"Isotopes: outcome 4","content":"Explain why isotopes of the same element have different physical properties, limited to mass and density.","topic":"1.2","objectives":["1.2.4"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":4}},{"level":"as_level","kind":"topic","knowledge_key":"topic|1.3","title":"Electrons, energy levels and atomic orbitals","content":"1.3 Electrons, energy levels and atomic orbitals","topic":"1.3","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"1"}},{"level":"as_level","kind":"content_scope","knowledge_key":"scope|1.3","title":"Electrons, energy levels and atomic orbitals","content":"Atomic structure: Electrons, energy levels and atomic orbitals. This subsection is part of the AS Level Chemistry 9701 syllabus.","topic":"1.3","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"1"}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|1","title":"Electrons, energy levels and atomic orbitals: outcome 1","content":"Understand shells, sub-shells, orbitals, principal quantum number n and ground state as applied to electronic configuration.","topic":"1.3","objectives":["1.3.1"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":1}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|2","title":"Electrons, energy levels and atomic orbitals: outcome 2","content":"Describe the number of orbitals and maximum electrons in s, p and d sub-shells.","topic":"1.3","objectives":["1.3.2"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":2}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|3","title":"Electrons, energy levels and atomic orbitals: outcome 3","content":"Describe the order of increasing sub-shell energy within the first three shells and the 4s and 4p sub-shells.","topic":"1.3","objectives":["1.3.3"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":3}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|4","title":"Electrons, energy levels and atomic orbitals: outcome 4","content":"Describe electronic configurations by shell, sub-shell and orbital.","topic":"1.3","objectives":["1.3.4"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":4}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|5","title":"Electrons, energy levels and atomic orbitals: outcome 5","content":"Explain electronic configurations in terms of electron energy and inter-electron repulsion.","topic":"1.3","objectives":["1.3.5"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":5}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|6","title":"Electrons, energy levels and atomic orbitals: outcome 6","content":"Determine electronic configurations of atoms and ions from proton number and charge using full or shorthand notation.","topic":"1.3","objectives":["1.3.6"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":6}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|7","title":"Electrons, energy levels and atomic orbitals: outcome 7","content":"Understand and use electrons-in-boxes notation.","topic":"1.3","objectives":["1.3.7"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":7}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|8","title":"Electrons, energy levels and atomic orbitals: outcome 8","content":"Describe and sketch the shapes of s and p orbitals.","topic":"1.3","objectives":["1.3.8"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":8}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.3|9","title":"Electrons, energy levels and atomic orbitals: outcome 9","content":"Describe a free radical as a species with one or more unpaired electrons.","topic":"1.3","objectives":["1.3.9"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":9}},{"level":"as_level","kind":"topic","knowledge_key":"topic|1.4","title":"Ionisation energy","content":"1.4 Ionisation energy","topic":"1.4","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"1"}},{"level":"as_l