_key":"outcome|1.4|6","title":"Ionisation energy: outcome 6","content":"Explain ionisation-energy factors using nuclear charge, atomic/ionic radius, shielding and spin-pair repulsion.","topic":"1.4","objectives":["1.4.6"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":6}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.4|7","title":"Ionisation energy: outcome 7","content":"Deduce electronic configurations from successive ionisation-energy data.","topic":"1.4","objectives":["1.4.7"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":7}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|1.4|8","title":"Ionisation energy: outcome 8","content":"Deduce an element''s position in the Periodic Table from successive ionisation-energy data.","topic":"1.4","objectives":["1.4.8"],"metadata":{"source":"structured-cambridge-dataset","section":"1","outcomeIndex":8}},{"level":"as_level","kind":"topic","knowledge_key":"topic|2","title":"Atoms, molecules and stoichiometry","content":"Topic 2: Atoms, molecules and stoichiometry.","topic":"2","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"2"}},{"level":"as_level","kind":"topic","knowledge_key":"topic|2.1","title":"Relative masses of atoms and molecules","content":"2.1 Relative masses of atoms and molecules","topic":"2.1","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"2"}},{"level":"as_level","kind":"content_scope","knowledge_key":"scope|2.1","title":"Relative masses of atoms and molecules","content":"Atoms, molecules and stoichiometry: Relative masses of atoms and molecules. This subsection is part of the AS Level Chemistry 9701 syllabus.","topic":"2.1","objectives":[],"metadata":{"source":"structured-cambridge-dataset","section":"2"}},{"level":"as_level","kind":"learning_outcome","knowledge_key":"outcome|2.1|1","title":"Relative masses of atoms and molecules: outc